/**
 * Unit tests for the TenantLoginProviderOidcClaimMappingAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantLoginProviderOidcClaimMappingAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getOidcClaimMapping returns null on a freshly created holder.
     */
    public function testOidcClaimMappingNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcClaimMappingAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isOidcClaimMappingAssigned());
        $this->assertNull($holder->getOidcClaimMapping());
    }
}
