    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedOidcClaimMappingRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultOidcClaimMapping();
    }
